        eq.unknowns = counts.size();
        for (auto [id, count] : counts) {
            eq.terms.emplace_back(id, count);
        }
        equations.push_back(move(eq));
    }

    vector<vector<pair<int, int>>> incidence(676);
    queue<int> ready;

    for (int i = 0; i < (int)equations.size(); ++i) {
        for (auto [id, count] : equations[i].terms) {
            incidence[id].emplace_back(i, count);
        }
        if (equations[i].unknowns == 1) {
            ready.push(i);
        }
    }

    vector<bool> solved(676, false);
    vector<cpp_int> value(676);

    while (!ready.empty()) {
        int ei = ready.front();
        ready.pop();

        Equation &eq = equations[ei];
        if (eq.unknowns != 1) continue;

        int variable = -1;
        int coefficient = 0;
        for (auto [id, count] : eq.terms) {
            if (!solved[id]) {
                variable = id;
                coefficient = count;
                break;
            }
        }

        if (variable == -1) continue;

        value[variable] = eq.residual / coefficient;
        solved[variable] = true;

        for (auto [otherEq, count] : incidence[variable]) {
            Equation &next = equations[otherEq];
            next.residual -= value[variable] * count;
            --next.unknowns;
            if (next.unknowns == 1) {
                ready.push(otherEq);
            }
        }
    }

    for (int id = 0; id < 676; ++id) {
        if (present[id]) {
            cout << char('a' + id / 26) << char('a' + id % 26)
                 << ' ' << value[id] << '\n';
        }
    }

    return 0;
}
